const topic = msg.topic || '';
let body = msg.payload;
if (Buffer.isBuffer(body)) body = body.toString();
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* availability is plain text */ } }
const received = new Date().toISOString();
const view = {topic, data: body, received_at: received};
const events = [];
if (topic.endsWith('/telemetry')) {
  flow.set('orchidTelemetryAt', Date.now());
  flow.set('orchidStaleLogged', false);
} else if (topic.endsWith('/availability')) {
  const wasOnline = flow.get('orchidOnline');
  flow.set('orchidOnline', body);
  if (body === 'offline' && wasOnline !== 'offline') flow.set('orchidOfflineSince', Date.now());
  if (body === 'online') {
    flow.set('orchidOfflineSince', 0);
    flow.set('orchidOfflineFiveMinuteLogged', false);
  }
  if ((body === 'online' || body === 'offline') && wasOnline !== body) events.push({event:'availability', state:body, at:received});
} else if (topic.endsWith('/state') && body && typeof body === 'object') {
  const current = {mist:body.mist, fan:body.fan, light:body.light};
  const previous = flow.get('orchidRelayState');
  if (previous) for (const relay of ['mist','fan','light']) {
    if (current[relay] !== undefined && previous[relay] !== current[relay]) events.push({event:'relay_change', relay, from:previous[relay], to:current[relay], at:received});
  }
  flow.set('orchidRelayState', current);
}
const history = events.map(e => ({payload:JSON.stringify(e)+'\n'}));
return [{payload:view}, history.length ? history : null];

const now = Date.now();
const online = flow.get('orchidOnline');
let seen = flow.get('orchidTelemetryAt') || 0;
const alerts = [];
if (online === 'offline') {
  let offlineSince = flow.get('orchidOfflineSince') || 0;
  if (!offlineSince) { offlineSince = now; flow.set('orchidOfflineSince', offlineSince); }
  if (!flow.get('orchidOfflineFiveMinuteLogged') && now - offlineSince >= 300000) {
    alerts.push({event:'device_offline_over_5m', duration_s:Math.floor((now-offlineSince)/1000), at:new Date(now).toISOString()});
    flow.set('orchidOfflineFiveMinuteLogged', true);
  }
} else if (online === 'online') {
  flow.set('orchidOfflineSince', 0);
  flow.set('orchidOfflineFiveMinuteLogged', false);
  if (!seen) { seen = now; flow.set('orchidTelemetryAt', seen); }
}
if (online === 'offline' && !flow.get('orchidOfflineLogged')) { alerts.push({event:'device_offline', at:new Date(now).toISOString()}); flow.set('orchidOfflineLogged', true); }
if (online === 'online') flow.set('orchidOfflineLogged', false);
if (seen && now - seen > 15000 && !flow.get('orchidStaleLogged')) { alerts.push({event:'telemetry_stale', age_s:Math.floor((now-seen)/1000), at:new Date(now).toISOString()}); flow.set('orchidStaleLogged', true); }
return alerts.map(a => ({payload:JSON.stringify(a)+'\n'}));

let data = msg.payload;
if (Buffer.isBuffer(data)) data = data.toString();
if (typeof data === 'string') { try { data = JSON.parse(data); } catch (err) { node.warn('Invalid telemetry JSON'); return null; } }
if (!data || typeof data !== 'object') return null;
const now = new Date().toISOString();
const events = [];
function numeric(value) {
  if (value === null || value === undefined || value === '') return NaN;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : NaN;
}
function evaluate(key, metric, value, onAt, offAt) {
  const previous = flow.get(key) === true;
  const active = previous ? value >= offAt : value > onAt;
  if (active !== previous) {
    flow.set(key, active);
    events.push({event:active ? 'threshold_active' : 'threshold_cleared', rule:key, metric, value, threshold:active ? onAt : offAt, at:now});
  }
}
const temperature = numeric(data.temperature_c);
if (Number.isFinite(temperature)) evaluate('orchidHighTemperature', 'temperature_c', temperature, 33, 31);
const humidity = numeric(data.humidity_pct);
if (Number.isFinite(humidity)) evaluate('orchidHighHumidity', 'humidity_pct', humidity, 90, 85);
const lightAdc = numeric(data.light_adc);
if (Number.isFinite(lightAdc)) evaluate('orchidLightDemand', 'light_adc', lightAdc, 2200, 1800);
return events.length ? [{payload:events.map(e => JSON.stringify(e)+'\n').join(''), events}] : null;

let data = msg.payload;
if (Buffer.isBuffer(data)) data = data.toString();
if (typeof data === 'string') { try { data = JSON.parse(data); } catch (err) { node.warn('Invalid telemetry JSON'); return null; } }
if (!data || typeof data !== 'object') return null;
const now = new Date().toISOString();
const events = [];
function numeric(value) {
  if (value === null || value === undefined || value === '') return NaN;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : NaN;
}
const water = numeric(data.water_adc);
const humidity = numeric(data.humidity_pct);
let waterLow = flow.get('orchidWaterLow');
if (Number.isFinite(water)) {
  if (waterLow === undefined) {
    waterLow = water < 1200;
    if (waterLow) events.push({event:'water_lockout', water_adc:water, threshold:1200, at:now});
  } else {
    const nextWaterLow = waterLow ? water < 1500 : water < 1200;
    if (nextWaterLow !== waterLow) events.push({event:nextWaterLow ? 'water_lockout' : 'water_recovered', water_adc:water, threshold:nextWaterLow ? 1200 : 1500, at:now});
    waterLow = nextWaterLow;
  }
  flow.set('orchidWaterLow', waterLow);
}
if (Number.isFinite(humidity) && Number.isFinite(water)) {
  const previousDemand = flow.get('orchidMistDemand') === true;
  const mistDemand = waterLow ? false : previousDemand ? humidity < 80 : humidity < 65;
  if (mistDemand !== previousDemand) {
    flow.set('orchidMistDemand', mistDemand);
    events.push({event:mistDemand ? 'mist_demand_observed' : 'mist_demand_cleared', humidity_pct:humidity, water_adc:water, at:now});
  }
}
return events.length ? [{payload:events.map(e => JSON.stringify(e)+'\n').join(''), events}] : null;

const inputTopic = msg.topic || '';
let data = msg.payload;
if (inputTopic !== 'dashboard/refresh') {
  if (data && typeof data === 'object' && data.data !== undefined) data = data.data;
  if (Buffer.isBuffer(data)) data = data.toString();
  if (typeof data === 'string' && !inputTopic.endsWith('/availability')) {
    try { data = JSON.parse(data); } catch (err) { node.warn('Invalid dashboard MQTT JSON'); return null; }
  }
}
const snapshot = flow.get('orchidDashboardSnapshot') || {
  temperature_c: null, humidity_pct: null, light_adc: null, water_adc: null,
  mist: '—', fan: '—', light: '—', mist_state: '—', mode: '—', availability: 'unknown',
  water_lockout: false, dht_fault: false, mist_mode: null, fan_mode: null, light_mode: null
};
// null tu firmware (DHT loi) phai hien thi la thieu du lieu, khong phai 0.
const numberOrNull = value => value === null || value === '' || !Number.isFinite(Number(value)) ? null : Number(value);
let telemetryUpdate = false;
if (inputTopic.endsWith('/telemetry') && data && typeof data === 'object') {
  for (const key of ['temperature_c','humidity_pct','light_adc','water_adc']) {
    if (data[key] !== undefined) snapshot[key] = numberOrNull(data[key]);
  }
  flow.set('orchidDashboardTelemetryAt', Date.now());
  snapshot.availability = 'online';
  telemetryUpdate = true;
} else if (inputTopic.endsWith('/state') && data && typeof data === 'object') {
  for (const key of ['mist','fan','light','mist_state','mode','mist_mode','fan_mode','light_mode']) {
    if (data[key] !== undefined) snapshot[key] = String(data[key]);
  }
  if (typeof data.water_lockout === 'boolean') snapshot.water_lockout = data.water_lockout;
  if (typeof data.dht_fault === 'boolean') snapshot.dht_fault = data.dht_fault;
  if (data.water_lockout === true) snapshot.mist_state = 'WATER_LOCKOUT';
} else if (inputTopic.endsWith('/availability')) {
  const availability = typeof data === 'string' ? data : String(data);
  if (availability === 'online' || availability === 'offline') snapshot.availability = availability;
}
flow.set('orchidDashboardSnapshot', snapshot);
const lastTelemetry = flow.get('orchidDashboardTelemetryAt') || 0;
const isStale = lastTelemetry > 0 && Date.now() - lastTelemetry > 15000;
const connection = snapshot.availability === 'offline' ? 'OFFLINE' : isStale ? 'STALE' : snapshot.availability === 'online' ? 'ONLINE' : 'WAITING';
flow.set('orchidDashboardConnection', connection);
const show = (value, suffix) => value === null ? '—' : `${value}${suffix}`;
const climate = (value, suffix) => snapshot.dht_fault ? 'DHT fault' : show(value, suffix);
const manualRelays = ['mist','fan','light'].filter(relay => snapshot[`${relay}_mode`] === 'MANUAL');
const modeText = snapshot.mode === 'MANUAL' && manualRelays.length ? `MANUAL (${manualRelays.join(', ')})` : snapshot.mode;
const climateHistory = telemetryUpdate ? [
  {topic:'Temperature °C', payload:snapshot.temperature_c},
  {topic:'Humidity %', payload:snapshot.humidity_pct}
].filter(point => Number.isFinite(point.payload)) : null;
const adcHistory = telemetryUpdate ? [
  {topic:'Light ADC', payload:snapshot.light_adc},
  {topic:'Water ADC', payload:snapshot.water_adc}
].filter(point => Number.isFinite(point.payload)) : null;
return [
  {payload:climate(snapshot.temperature_c, ' °C')},
  {payload:climate(snapshot.humidity_pct, ' %')},
  {payload:show(snapshot.light_adc, '')},
  {payload:show(snapshot.water_adc, '')},
  {payload:snapshot.mist_state},
  {payload:snapshot.fan},
  {payload:snapshot.light},
  {payload:connection},
  {payload:modeText},
  climateHistory,
  adcHistory,
  {topic:'dashboard/snapshot', payload:{...snapshot, connection}}
];

// Nhan su kien tu widget dieu khien. Quyen lay tu tai khoan dang nhap (settings.js), khong tu client.
const TTL_CHOICES = [60, 300, 900, 1800, 3600];
const lookup = global.get('orchidDashboardUser');
const session = typeof lookup === 'function' && msg._client ? lookup(msg._client.socketId) : null;
const user = session ? session.user : null;
const role = session ? session.role : null;
const canControl = role === 'admin' || role === 'operator';
const client = msg._client && msg._client.socketId ? {socketId: msg._client.socketId} : null;
const at = new Date().toISOString();
const currentMode = global.get('orchidControlMode') || 'AUTO';
const commands = [];
const events = [];
let modeSync = null;
let ttlSync = null;
let notify = null;

function deny(action) {
  events.push({event:'control_denied', action, user, role, at});
  notify = {payload:`Account ${user || '(not logged in)'} (${role || 'no role'}) cannot ${action}.`, _client: client || undefined};
}

if (msg.topic === 'control/init') {
  global.set('orchidControlMode', currentMode);
  if (!TTL_CHOICES.includes(flow.get('orchidControlTtl'))) flow.set('orchidControlTtl', 300);
  modeSync = {payload: currentMode};
  ttlSync = {payload: flow.get('orchidControlTtl')};
} else if (msg.topic === 'control/mode') {
  const requested = msg.payload;
  if (requested !== 'AUTO' && requested !== 'MANUAL') return null;
  if (!canControl) {
    deny('change control mode');
    modeSync = {payload: currentMode};
  } else if (requested !== currentMode) {
    global.set('orchidControlMode', requested);
    events.push({event:'control_mode_changed', from: currentMode, to: requested, user, at});
    if (requested === 'AUTO') {
      // Ve AUTO: xoa moi override dang giu tren firmware, roi automation tuan 7 tiep quan.
      for (const relay of ['mist','fan','light']) {
        commands.push({topic:'orchid/command', payload:{relay, mode:'AUTO', source:'dashboard', user, role, client, reason:'mode_auto'}});
      }
    }
  }
} else if (msg.topic === 'control/ttl') {
  const ttl = Number(msg.payload);
  if (!canControl) {
    deny('change command TTL');
    ttlSync = {payload: flow.get('orchidControlTtl') || 300};
  } else if (TTL_CHOICES.includes(ttl)) {
    flow.set('orchidControlTtl', ttl);
  }
} else if (msg.topic === 'control/relay') {
  const [relay, state] = String(msg.payload || '').split(':');
  const ttl = flow.get('orchidControlTtl') || 300;
  // Quyen, che do va khoa duoc kiem tra lai trong gateway; o day chi dong goi yeu cau.
  commands.push({topic:'orchid/command', payload:{relay, mode:'MANUAL', state, ttl_s: ttl, source:'dashboard', user, role, client, reason:'operator_button'}});
} else {
  return null;
}

const eventLines = events.map(event => ({payload: JSON.stringify(event) + '\n'}));
return [
  commands.length ? commands : null,
  modeSync,
  ttlSync,
  eventLines.length ? eventLines : null,
  notify,
  {topic:'control/refresh'}
];

// Cong lenh duy nhat toi firmware: kiem tra quyen/che do/ket noi, gui dung topic + payload,
// theo doi ACK theo request_id, het han NO_ACK va ghi lich su. An toan thiet bi van do firmware quyet.
const DEVICE_TOPIC = 'garden/orchid/orchid-01';
const RELAYS = ['mist', 'fan', 'light'];
const ACK_TIMEOUT_MS = 6000;
const HISTORY_LIMIT = 25;
const now = Date.now();
const at = new Date(now).toISOString();
const topic = msg.topic || '';
const pending = flow.get('orchidPendingCommands') || {};
const timedOut = flow.get('orchidTimedOutCommands') || {};
let history = flow.get('orchidCommandHistory') || [];
const mqtt = [];
const events = [];
const notifications = [];
const results = [];
let lastText = null;
let historyChanged = false;

const describe = command => command.mode === 'AUTO' ? 'AUTO' : `MANUAL ${command.state} ${command.ttl_s}s`;
const sourceLabel = command => command.source === 'dashboard' ? `dashboard (${command.user || '?'})` : command.source;
const clock = time => new Date(time).toLocaleTimeString('en-GB', {hour12: false});

function upsertHistory(command, result, detail, latency) {
  const key = command.request_id || command.local_id;
  const row = {
    key,
    time: clock(command.sent_at || now),
    source: sourceLabel(command),
    relay: command.relay,
    command: describe(command),
    result,
    detail: detail || '',
    latency: latency === undefined ? '' : `${latency} ms`
  };
  const index = history.findIndex(item => item.key === key);
  if (index >= 0) history[index] = row; else history.unshift(row);
  history = history.slice(0, HISTORY_LIMIT);
  historyChanged = true;
}

function finish(command, result, reason, latency) {
  const outcome = {
    request_id: command.request_id || null, ref: command.ref || null, relay: command.relay,
    mode: command.mode, state: command.state, ttl_s: command.ttl_s, source: command.source,
    user: command.user || null, result, reason: reason || null, latency_ms: latency, at
  };
  results.push({topic: 'orchid/command_result', payload: outcome});
  events.push({event: 'command_result', ...outcome});
  upsertHistory(command, result, reason, latency);
  const text = `${command.relay} ${describe(command)} → ${result}${reason ? ` (${reason})` : ''}${latency === undefined ? '' : `, ${latency} ms`}`;
  if (command.source === 'dashboard') lastText = text;
  // Thong bao cho dung client da bam nut; lenh automation chi bao khi that bai.
  if (command.source === 'dashboard' || result !== 'APPLIED') {
    const color = result === 'APPLIED' ? '#26734d' : result === 'NO_ACK' ? '#b7791f' : '#c53030';
    notifications.push({payload: text, ui_update: {color}, _client: command.client || undefined});
  }
}

if (topic === 'orchid/command') {
  const request = msg.payload || {};
  const command = {
    relay: request.relay, mode: request.mode,
    state: request.mode === 'MANUAL' ? request.state : undefined,
    ttl_s: request.mode === 'MANUAL' ? request.ttl_s : undefined,
    source: String(request.source || 'unknown'), user: request.user || null,
    client: request.client || null, ref: request.ref || null, reason: request.reason || null
  };
  const controlMode = global.get('orchidControlMode') || 'AUTO';
  const connection = flow.get('orchidDashboardConnection') || 'WAITING';
  const isDashboard = command.source === 'dashboard';
  const isAutomation = command.source.startsWith('automation:');
  let reject = null;
  if (!RELAYS.includes(command.relay)) reject = 'INVALID_RELAY';
  else if (command.mode !== 'AUTO' && command.mode !== 'MANUAL') reject = 'INVALID_MODE';
  else if (command.mode === 'MANUAL' && command.state !== 'ON' && command.state !== 'OFF') reject = 'INVALID_STATE';
  else if (command.mode === 'MANUAL' && !(Number.isInteger(command.ttl_s) && command.ttl_s >= 1 && command.ttl_s <= 3600)) reject = 'INVALID_TTL';
  else if (!isDashboard && !isAutomation) reject = 'UNKNOWN_SOURCE';
  else if (isDashboard && request.role !== 'admin' && request.role !== 'operator') reject = 'FORBIDDEN';
  else if (isDashboard && command.mode === 'MANUAL' && controlMode !== 'MANUAL') reject = 'LOCKED_AUTO_MODE';
  else if (isAutomation && controlMode !== 'AUTO') reject = 'AUTOMATION_SUSPENDED';
  else if (connection !== 'ONLINE') reject = `DEVICE_${connection}`;
  else if (Object.values(pending).some(item => item.relay === command.relay)) reject = 'BUSY';

  if (reject) {
    command.local_id = `local-${now.toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
    command.sent_at = now;
    finish(command, 'BLOCKED', reject);
  } else {
    const sequence = (flow.get('orchidCommandSeq') || 0) + 1;
    flow.set('orchidCommandSeq', sequence);
    command.request_id = `${isDashboard ? 'dash' : 'auto'}-${now.toString(36)}-${sequence}`;
    command.sent_at = now;
    const payload = command.mode === 'AUTO'
      ? {request_id: command.request_id, mode: 'AUTO'}
      : {request_id: command.request_id, mode: 'MANUAL', state: command.state, ttl_s: command.ttl_s};
    pending[command.request_id] = command;
    mqtt.push({topic: `${DEVICE_TOPIC}/cmd/${command.relay}`, payload: JSON.stringify(payload), qos: 1, retain: false});
    events.push({event: 'command_sent', request_id: command.request_id, ref: command.ref, relay: command.relay,
      payload, source: command.source, user: command.user, reason: command.reason, at});
    upsertHistory(command, 'PENDING', 'waiting for ACK');
    if (isDashboard) lastText = `${command.relay} ${describe(command)} → sent, waiting for ACK`;
  }
} else if (topic.endsWith('/ack')) {
  let body = msg.payload;
  if (Buffer.isBuffer(body)) body = body.toString();
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (err) { node.warn('Invalid ACK JSON'); return null; } }
  const requestId = body && body.request_id;
  const command = requestId ? pending[requestId] : null;
  if (!command) {
    if (requestId && timedOut[requestId]) events.push({event: 'command_late_ack', request_id: requestId, result: body.result, reason: body.reason || null, at});
    else return null;
  } else {
    delete pending[requestId];
    const result = body.result === 'APPLIED' || body.result === 'REJECTED' ? body.result : 'INVALID_ACK';
    finish(command, result, body.reason || null, now - command.sent_at);
  }
} else if (topic === 'gateway/tick') {
  for (const [requestId, command] of Object.entries(pending)) {
    if (now - command.sent_at >= ACK_TIMEOUT_MS) {
      delete pending[requestId];
      timedOut[requestId] = now;
      finish(command, 'NO_ACK', `no ACK within ${ACK_TIMEOUT_MS / 1000}s`);
    }
  }
  for (const [requestId, time] of Object.entries(timedOut)) if (now - time > 60000) delete timedOut[requestId];
} else {
  return null;
}

flow.set('orchidPendingCommands', pending);
flow.set('orchidTimedOutCommands', timedOut);
flow.set('orchidCommandHistory', history);
const lines = events.map(event => ({payload: JSON.stringify(event) + '\n'}));
const tableRows = history.map(({key, ...row}) => row);
const outputs = [
  mqtt.length ? mqtt : null,
  historyChanged ? {payload: tableRows} : null,
  lastText ? {payload: lastText} : null,
  notifications.length ? notifications : null,
  lines.length ? lines : null,
  results.length || mqtt.length ? [...results, {topic: 'control/refresh'}] : null
];
return outputs.some(Boolean) ? outputs : null;

// Tinh trang thai khoa cua 6 nut tu che do dashboard, ket noi, trang thai firmware va lenh dang cho ACK.
const BUTTONS = ['mist:ON', 'mist:OFF', 'fan:ON', 'fan:OFF', 'light:ON', 'light:OFF'];
const snapshot = flow.get('orchidDashboardSnapshot') || {};
const connection = flow.get('orchidDashboardConnection') || 'WAITING';
const mode = global.get('orchidControlMode') || 'AUTO';
const pendingRelays = new Set(Object.values(flow.get('orchidPendingCommands') || {}).map(command => command.relay));
const reasons = [];
let allowed = true;
if (mode !== 'MANUAL') { allowed = false; reasons.push('AUTO mode: manual buttons locked'); }
if (connection !== 'ONLINE') { allowed = false; reasons.push(`Device ${connection}: commands blocked`); }
const mistOnBlock = snapshot.dht_fault ? 'SENSOR_FAULT'
  : snapshot.water_lockout ? 'WATER_LOCKOUT'
  : ['COOLDOWN', 'WATER_LOCKOUT', 'SENSOR_FAULT'].includes(snapshot.mist_state) ? snapshot.mist_state : null;
if (allowed && mistOnBlock) reasons.push(`Mist ON blocked by firmware state ${mistOnBlock}`);
for (const relay of pendingRelays) reasons.push(`Waiting for ACK: ${relay}`);
const enabled = {};
for (const key of BUTTONS) {
  const [relay, state] = key.split(':');
  enabled[key] = allowed && !pendingRelays.has(relay) && !(relay === 'mist' && state === 'ON' && mistOnBlock);
}
const lockText = reasons.length ? reasons.join(' · ') : 'Ready: manual commands enabled';
// Sau deploy widget co the mat trang thai -> lan init gui lai toan bo.
const previous = msg.topic === 'control/init' ? {} : flow.get('orchidControlLastUi') || {};
flow.set('orchidControlLastUi', {...enabled, lockText});
return [
  ...BUTTONS.map(key => previous[key] === enabled[key] ? null : {enabled: enabled[key]}),
  previous.lockText === lockText ? null : {payload: lockText}
];

// Kiem tra va nap cau hinh rule tuan 7. Cau hinh sai thi giu ban cu (hoac khong chay rule).
const input = msg.payload || {};
const errors = [];
const time = (value, name) => {
  if (typeof value !== 'string' || !/^([01]\d|2[0-3]):[0-5]\d$/.test(value)) errors.push(`${name} must be HH:MM`);
  return value;
};
const number = (value, name, min, max) => {
  if (!Number.isFinite(value) || value < min || value > max) errors.push(`${name} must be ${min}..${max}`);
  return value;
};
const clockIn = input.clock || {};
const lightIn = input.light || {};
const fanIn = input.fan_assist || {};
const nightIn = input.night_policy || {};
const config = {
  clock: {
    speed: number(clockIn.speed === undefined ? 1 : clockIn.speed, 'clock.speed', 1, 600),
    start_local: clockIn.start_local ? time(clockIn.start_local, 'clock.start_local') : ''
  },
  light: {
    enabled: lightIn.enabled !== false,
    window_start: time(lightIn.window_start, 'light.window_start'),
    off_time: time(lightIn.off_time, 'light.off_time'),
    dark_on_adc: number(lightIn.dark_on_adc, 'light.dark_on_adc', 0, 4095),
    bright_off_adc: number(lightIn.bright_off_adc, 'light.bright_off_adc', 0, 4095),
    daily_max_on_min: number(lightIn.daily_max_on_min, 'light.daily_max_on_min', 1, 1440),
    hold_ttl_s: number(lightIn.hold_ttl_s, 'light.hold_ttl_s', 60, 3600)
  },
  fan_assist: {
    enabled: fanIn.enabled !== false,
    duration_s: number(fanIn.duration_s, 'fan_assist.duration_s', 10, 1800),
    max_per_day: number(fanIn.max_per_day, 'fan_assist.max_per_day', 1, 200)
  },
  night_policy: {
    care_start: time(nightIn.care_start, 'night_policy.care_start'),
    care_end: time(nightIn.care_end, 'night_policy.care_end'),
    allow_auto_mist_at_night: nightIn.allow_auto_mist_at_night === true,
    team_confirmed: nightIn.team_confirmed === true,
