const controlMode = global.get('orchidControlMode') || 'AUTO';
const previousMode = flow.get('orchidWeek7ControlMode');
flow.set('orchidWeek7ControlMode', controlMode);
msg.kind = kind;
msg.realNow = realNow;
msg.ruleNow = clock.ruleStart + (realNow - clock.realStart) * clock.speed;
