// Rule 1 - den theo khung gio + nguong sang, co gio tat va gioi han tong thoi luong bat trong ngay.
// Chi phat lenh khi dashboard o AUTO; lenh ON co TTL <= ngan sach con lai nen firmware tu nha neu Node-RED dung.
const RULE = 'light_schedule';
const SOURCE = `automation:${RULE}`;
const cfg = msg.config.light;
const {realNow, ruleNow, speed, device} = msg;
