    sent: null, retryAfter: 0, limitLogged: false, seq: 0, status: null};
}
const pad = value => String(value).padStart(2, '0');
const toMinutes = value => { const [hours, minutes] = value.split(':').map(Number); return hours * 60 + minutes; };
const ruleDate = new Date(ruleNow);
const ruleTime = `${ruleDate.getFullYear()}-${pad(ruleDate.getMonth() + 1)}-${pad(ruleDate.getDate())} ${pad(ruleDate.getHours())}:${pad(ruleDate.getMinutes())}:${pad(ruleDate.getSeconds())}`;
const day = ruleTime.slice(0, 10);
const minute = ruleDate.getHours() * 60 + ruleDate.getMinutes() + ruleDate.getSeconds() / 60;
const at = new Date(realNow).toISOString();
const events = [];
const commands = [];

if (st.day !== day) {
