      if (result.result === 'APPLIED') {
        st.sent.appliedAt = realNow;
      } else {
        if (result.reason !== 'BUSY') events.push({event: 'automation_command_failed', rule: RULE, ref: result.ref, result: result.result, reason: result.reason, rule_time: ruleTime, at});
