    }
  }
}

const rawAdc = device.telemetry ? device.telemetry.light_adc : null;
const hasAdc = rawAdc !== null && rawAdc !== undefined && rawAdc !== '' && Number.isFinite(Number(rawAdc));
const adc = hasAdc ? Number(rawAdc) : null;
if (hasAdc) st.dark = st.dark ? adc >= cfg.bright_off_adc : adc > cfg.dark_on_adc;
const start = toMinutes(cfg.window_start);
const off = toMinutes(cfg.off_time);
const inWindow = start <= off ? minute >= start && minute < off : minute >= start || minute < off;
const remainingMs = Math.max(0, cfg.daily_max_on_min * 60000 - st.onMs);
let desired;
let reason;
if (!cfg.enabled) { desired = null; reason = 'rule_disabled'; }
else if (!inWindow) { desired = 'OFF'; reason = 'outside_schedule'; }
else if (remainingMs <= 0) { desired = 'OFF'; reason = 'daily_limit_reached'; }
else if (!hasAdc) { desired = null; reason = 'no_light_reading'; }
