}
const minutesToOff = (off - minute + 1440) % 1440;
const ruleTtlS = desired === 'ON' ? Math.min(cfg.hold_ttl_s, remainingMs / 1000, minutesToOff * 60) : cfg.hold_ttl_s;
const ttlS = Math.min(3600, Math.max(desired === 'ON' ? 1 : 5, Math.ceil(ruleTtlS / speed)));

const active = msg.controlMode === 'AUTO' && device.connection === 'ONLINE';
