// Giam sat tinh huong bat thuong: DHT loi lien tiep, nuoc thap, mat ket noi, lenh khong ACK,
// va kiem tra tu ben ngoai rang firmware van giu khoa nuoc / khoa cam bien / gioi han thoi gian phun.
const MAX_MIST_ON_S = 130;  // firmware gioi han 120 s; du 10 s cho tre MQTT
const NO_ACK_CLEAR_MS = 300000;
const SAFE_STATE = {
  dht_fault: 'Firmware SENSOR_FAULT: AUTO misting stopped, mist ON rejected; fan holds last state; light unaffected',
  water_low: 'Firmware WATER_LOCKOUT: mist relay locked until water ADC >= 1500',
  link_offline: 'Device offline (LWT): firmware cleared manual overrides and runs local AUTO with safety limits; dashboard commands blocked',
  telemetry_stale: 'No telemetry for >15 s: dashboard commands blocked; values on screen are old',
  ack_missing: 'Command not confirmed by firmware: trust device state only; check link before retrying',
  violation_mist_lockout: 'CRITICAL: mist reported ON during water lockout - stop and check firmware/relay',
  violation_mist_sensor: 'CRITICAL: mist reported ON during DHT fault - stop and check firmware',
  violation_mist_runtime: `CRITICAL: mist ON longer than ${MAX_MIST_ON_S}s - stop and check firmware/relay`
};
const SEVERITY = {violation_mist_lockout: 'critical', violation_mist_sensor: 'critical', violation_mist_runtime: 'critical',
  dht_fault: 'fault', water_low: 'fault', link_offline: 'fault', telemetry_stale: 'warning', ack_missing: 'warning'};
