const events = [];
const notifications = [];
const state = device.state || {};
const telemetry = device.telemetry || {};

if (msg.kind === 'command_result') {
  const result = msg.payload || {};
  if (result.result === 'NO_ACK') {
    st.noAck[result.relay] = realNow;
    events.push({event: 'fault_command_no_ack', relay: result.relay, request_id: result.request_id, source: result.source,
