const mistOn = device.connection !== 'OFFLINE' && state.mist === 'ON';
if (mistOn && st.mistOnSince === null) st.mistOnSince = realNow;
if (!mistOn) st.mistOnSince = null;
const dhtFault = state.dht_fault === true || (telemetry.temperature_c === null && Number(telemetry.dht_fail_streak) >= 3);
const conditions = {
  dht_fault: dhtFault,
  water_low: state.water_lockout === true,
  link_offline: device.connection === 'OFFLINE',
  telemetry_stale: device.connection === 'STALE',
  ack_missing: Object.keys(st.noAck).length > 0,
  violation_mist_lockout: mistOn && state.water_lockout === true,
  violation_mist_sensor: mistOn && state.dht_fault === true,
  violation_mist_runtime: st.mistOnSince !== null && realNow - st.mistOnSince > MAX_MIST_ON_S * 1000
};
for (const [fault, isActive] of Object.entries(conditions)) {
  const wasActive = st.active[fault] === true;
  if (isActive === wasActive) continue;
  st.active[fault] = isActive;
  const detail = fault === 'dht_fault' ? {dht_fail_streak: telemetry.dht_fail_streak ?? null, mist_state: state.mist_state || null}
    : fault === 'water_low' ? {water_adc: telemetry.water_adc ?? null, mist_state: state.mist_state || null}
    : fault === 'ack_missing' ? {relays: Object.keys(st.noAck)}
    : fault.startsWith('violation') ? {mist: state.mist, mist_state: state.mist_state || null}
    : {connection: device.connection};
  events.push({event: isActive ? 'fault_active' : 'fault_cleared', fault, severity: SEVERITY[fault], ...detail,
    safe_state: isActive ? SAFE_STATE[fault] : null, at});
  if (isActive) {
    notifications.push({payload: `${SEVERITY[fault].toUpperCase()}: ${fault} - ${SAFE_STATE[fault]}`,
      ui_update: {color: SEVERITY[fault] === 'warning' ? '#b7791f' : '#c53030'}});
  } else {
    notifications.push({payload: `Cleared: ${fault}`, ui_update: {color: '#26734d'}});
  }
}
const order = ['critical', 'fault', 'warning'];
const activeFaults = Object.keys(st.active).filter(fault => st.active[fault])
  .sort((left, right) => order.indexOf(SEVERITY[left]) - order.indexOf(SEVERITY[right]));
const status = activeFaults.length
  ? activeFaults.map(fault => `${SEVERITY[fault].toUpperCase()} ${fault}: ${SAFE_STATE[fault]}`).join(' | ')
  : `OK: no active faults (device ${device.connection})`;
const statusChanged = status !== st.status;
st.status = status;
flow.set('orchidW7Faults', st);
return [
  events.length ? events.map(event => ({payload: JSON.stringify(event) + '\n', event})) : null,
  statusChanged ? {payload: status} : null,
  notifications.length ? notifications : null
];

// Bang su kien automation / an toan gan nhat cho dashboard (log day du nam trong orchid-history.jsonl).
const event = msg.event;
if (!event || typeof event !== 'object') return null;
const rows = flow.get('orchidW7EventRows') || [];
const {event: name, rule, fault, at, rule_time: ruleTime, ...rest} = event;
const detail = Object.entries(rest)
  .filter(([key, value]) => value !== null && value !== undefined && key !== 'safe_state')
  .map(([key, value]) => `${key}=${typeof value === 'object' ? JSON.stringify(value) : value}`)
  .join(' ');
rows.unshift({
  time: new Date(at || Date.now()).toLocaleTimeString('en-GB', {hour12: false}),
  rule_clock: ruleTime ? ruleTime.slice(11) : '',
  event: name,
  rule: rule || fault || '',
  detail
});
const trimmed = rows.slice(0, 20);
flow.set('orchidW7EventRows', trimmed);
return {payload: trimmed};
